import fs from 'node:fs';
import path from 'node:path';
import {fileURLToPath} from 'node:url';
import {createHash} from 'node:crypto';
const root=fileURLToPath(new URL('../',import.meta.url));
const read=f=>fs.readFileSync(path.join(root,f),'utf8');
const json=f=>JSON.parse(read(f));
const write=(f,v)=>fs.writeFileSync(path.join(root,f),JSON.stringify(v,null,2)+'\n');
const hash=f=>createHash('sha256').update(read(f)).digest('hex');
const expressionSource=JSON.parse(fs.readFileSync(path.join(root,'../MemoryLab/content/current/contracts/portrait-expressions.json'),'utf8'));
fs.writeFileSync(path.join(root,'server/shared/expression-catalog.js'),'// Generated by scripts/build-agent-bundle.mjs from MemoryLab/content/current/contracts/portrait-expressions.json.\n'+'export const EXPRESSION_CATALOG = '+JSON.stringify(expressionSource,null,2)+';\n');
const registry=json('main-agent/config/skill-registry.json');
const ids=new Set(registry.skills.map(s=>s.id));
const files=dir=>fs.readdirSync(path.join(root,dir),{withFileTypes:true}).flatMap(e=>e.isDirectory()?files(dir+'/'+e.name):[dir+'/'+e.name]).sort();
const lock={sourceRoot:'skills',files:files('skills').filter(f=>ids.has(f.split('/')[1])||f.startsWith('skills/call-companion/')).map(f=>({path:f.slice(7),sha256:hash(f)}))};
write('main-agent/config/skills-source-lock.json',lock);
const imported=[...files('main-agent').filter(f=>f!=='main-agent/import-manifest.json'),...lock.files.map(f=>'skills/'+f.path)];
write('main-agent/import-manifest.json',{bundle:'z-chat-singing-v2',files:imported.map(f=>({path:f,sha256:hash(f)}))});
const bundle={
 policy:json('main-agent/config/skills-scheduling.json'),registry,
 hostPrompt:read('main-agent/prompts/main-agent-skills.txt'),
 conversationPrompt:read('main-agent/prompts/conversation-host.txt'),
 callPrompt:files('skills/call-companion').filter(f=>f.endsWith('.md')).map(read).join('\n\n'),
 topicPrompt:read('main-agent/prompts/topic-progress.txt'),
 skills:Object.fromEntries(registry.skills.map(s=>[s.id,{instructions:read(s.entry),contract:read(s.contract),...(s.id==='singing'?{expression:read('skills/singing/references/expression.md')}:{})}])),
 review:{prompt:read('skills/audience-reaction/references/dialogue-review.md'),release:read('skills/audience-reaction/references/host-release-review.md'),repair:read('skills/audience-reaction/references/host-sentence-repair.md'),quality:read('skills/audience-reaction/references/host-turn-quality.md'),version:createHash('sha256').update(['dialogue-review','host-release-review','host-sentence-repair','host-turn-quality'].map(name=>read('skills/audience-reaction/references/'+name+'.md')).join('\n')).digest('hex')},
 version:'z-chat-singing-v2'
};
fs.writeFileSync(path.join(root,'server/shared/worker/agent-bundle-data.js'),'// Generated by scripts/build-agent-bundle.mjs. Server only.\nexport const AGENT_BUNDLE = '+JSON.stringify(bundle)+';\n');
console.log('Built chat/singing agent bundle from verified source files.');
